// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // The admin is the deployer (this test contract, since admin = msg.sender in constructor).
        // Only admin calls succeed, so restrict the caller domain to the admin by calling directly.
        vm.prank(address(this));
        bool ok;
        bool returned;
        try c.setOwner(newOwner) returns (bool success) {
            ok = true;
            returned = success;
        } catch {
            ok = false;
            returned = true; // vacuous in the revert branch
        }
        assertTrue(ok && returned && c.owner() == newOwner);
    }
}
